using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Xml.Linq;
using Hifc.Reference;

internal static class Program
{
    static int tests, failures;
    static string output;
    static void Check(string name, Action body) { tests++; try { body(); Console.WriteLine("PASS " + name); } catch (Exception ex) { failures++; Console.WriteLine("FAIL " + name + ": " + ex.Message); } }
    internal static void Assert(bool value, string detail) { if (!value) throw new Exception(detail); }
    static void Reject(Action body) { try { body(); } catch (InvalidOperationException) { return; } throw new Exception("expected rejection"); }
    internal static RedlinePoint P(int i, double x, double y) => new RedlinePoint { Sequence=i, X=x, Y=y };
    internal static RedlineOutline Square(double dx=0, double dy=0) => new RedlineOutline { Vertices=new[]{P(1,dx,dy),P(2,10+dx,dy),P(3,10+dx,10+dy),P(4,dx,10+dy)} };
    internal static RedlineData ManualData() => new RedlineData { Points=Square().Vertices, Accepted=true, Unit=RedlineUnit.Meters, Frame=RedlineFrame.Internal, Axes=RedlineAxes.XEastYNorth };
    static RedlineCarrier Carrier(string role, int id, double bottom, double top) => new RedlineCarrier { Role=role,ElementId=id,Outline=Square(),SolidVerified=true,BottomM=bottom,TopM=top };
    // A hand-authored independent XLSX fixture catches a reader which assumes shared strings,
    // guesses blank values as zero, or uses the wrong sheet relationship.
    internal static string Workbook(string name, string rows, bool formula=false, string title="规划净用地红线点")
    {
        var path=Path.Combine(output,name+"-"+Guid.NewGuid().ToString("N")+".xlsx");
        using(var zip=ZipFile.Open(path,ZipArchiveMode.Create)) {
            Entry(zip,"xl/workbook.xml","<workbook xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='Sheet1' sheetId='1' r:id='rId7'/></sheets></workbook>");
            Entry(zip,"xl/_rels/workbook.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId7' Target='worksheets/manual.xml' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet'/></Relationships>");
            Entry(zip,"xl/worksheets/manual.xml","<worksheet xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><sheetData><row r='1'><c r='A1' t='inlineStr'><is><t>"+title+"</t></is></c></row><row r='2'><c r='A2' t='inlineStr'><is><t>序号</t></is></c><c r='B2' t='inlineStr'><is><t>图纸的X坐标</t></is></c><c r='C2' t='inlineStr'><is><t>图纸的Y坐标</t></is></c></row>"+rows+"</sheetData><mergeCells count='1'><mergeCell ref='A1:C1'/></mergeCells></worksheet>");
        }
        return path;
    }
    static void Entry(ZipArchive zip,string name,string text) { using(var writer=new StreamWriter(zip.CreateEntry(name).Open()))writer.Write(text); }
    internal static string Rows() => "<row r='3'><c r='A3'><v>1</v></c><c r='B3'><v>0</v></c><c r='C3'><v>0</v></c></row><row r='4'><c r='A4'><v>2</v></c><c r='B4'><v>10</v></c><c r='C4'><v>0</v></c></row><row r='5'><c r='A5'><v>3</v></c><c r='B5'><v>10</v></c><c r='C5'><v>10</v></c></row><row r='6'><c r='A6'><v>4</v></c><c r='B6'><v>0</v></c><c r='C6'><v>10</v></c></row>";
    [STAThread] public static int Main(string[] args)
    {
        output=Path.GetFullPath(args.Length>0?args[0]:"redline-validation");Directory.CreateDirectory(output);
        Check("manual_metadata_unknown_never_passes",()=>{var data=ManualData();data.Unit=RedlineUnit.Unknown;Assert(!RedlineComparison.Manual(data,Square(),.01).Passed,"unknown unit passed");data.Unit=RedlineUnit.Meters;data.Frame=RedlineFrame.Unknown;Assert(!RedlineComparison.Manual(data,Square(),.01).Passed,"unknown frame passed");data.Frame=RedlineFrame.Shared;data.Axes=RedlineAxes.Unknown;Assert(!RedlineComparison.Manual(data,Square(),.01).Passed,"unknown XY convention passed");});
        Check("unaccepted_or_model_derived_points_never_pass",()=>{var data=ManualData();data.Accepted=false;Assert(!RedlineComparison.Manual(data,Square(),.01).Passed,"unaccepted points passed");data.Accepted=true;data.Source="MODEL";Assert(!RedlineComparison.Manual(data,Square(),.01).Passed,"model-derived points passed");});
        Check("millimeter_manual_points_are_scaled",()=>{var data=ManualData();data.Unit=RedlineUnit.Millimeters;foreach(var p in data.Points){p.X*=1000;p.Y*=1000;}Assert(RedlineComparison.Manual(data,Square(),.001).Passed,"millimeter conversion failed");});
        Check("sequence_gaps_and_duplicate_numbers_block",()=>{var data=ManualData();data.Points[2].Sequence=5;Assert(!RedlineDataPolicy.Validate(data).ValidCoordinates,"sequence gap accepted");data.Points[2].Sequence=2;Assert(!RedlineDataPolicy.Validate(data).ValidCoordinates,"duplicate accepted");});
        Check("closed_final_point_is_allowed_and_remains_manual",()=>{var data=ManualData();data.Points=data.Points.Concat(new[]{P(5,0,0)}).ToArray();var v=RedlineDataPolicy.Validate(data);Assert(v.ValidCoordinates&&v.ExplicitClosure,"explicit closure rejected");Assert(RedlineComparison.Manual(data,Square(),.01).Passed,"closed ring differs");});
        Check("self_intersection_and_repeated_inner_vertex_block",()=>{var data=ManualData();data.Points=new[]{P(1,0,0),P(2,10,10),P(3,0,10),P(4,10,0)};Assert(!RedlineDataPolicy.Validate(data).ValidCoordinates,"bow tie accepted");data.Points=new[]{P(1,0,0),P(2,10,0),P(3,10,10),P(4,10,0),P(5,0,10)};Assert(!RedlineDataPolicy.Validate(data).ValidCoordinates,"repeated inner vertex accepted");});
        Check("nonfinite_coordinates_block",()=>{var data=ManualData();data.Points[0].X=double.NaN;Assert(!RedlineDataPolicy.Validate(data).ValidCoordinates,"NaN accepted");});
        Check("identical_reverse_and_extra_collinear_vertices_pass",()=>{var b=Square();b.Vertices=new[]{P(1,0,0),P(2,0,10),P(3,10,10),P(4,10,0),P(5,5,0)};Assert(RedlineComparison.Outlines(Square(),b,.001).Passed,"equivalent outline rejected");});
        Check("equal_area_offset_shape_fails",()=>Assert(!RedlineComparison.Outlines(Square(),Square(2),.01).Passed,"offset same area passed"));
        Check("equal_area_different_shape_fails",()=>{var b=new RedlineOutline{Vertices=new[]{P(1,0,0),P(2,20,0),P(3,20,5),P(4,0,5)}};Assert(!RedlineComparison.Outlines(Square(),b,.01).Passed,"same area rectangle passed");});
        Check("concave_boundary_difference_is_detected_between_vertices",()=>{var a=new RedlineOutline{Vertices=new[]{P(1,0,0),P(2,10,0),P(3,10,10),P(4,7,10),P(5,7,3),P(6,3,3),P(7,3,10),P(8,0,10)}};var b=new RedlineOutline{Vertices=new[]{P(1,0,0),P(2,10,0),P(3,10,10),P(4,0,10)}};Assert(!RedlineComparison.Outlines(a,b,.01).Passed,"notch disappeared");});
        Check("horizontal_tolerance_is_visible_and_enforced",()=>{var result=RedlineComparison.Outlines(Square(),Square(.005),.01);Assert(result.Passed&&result.MaximumDeviationM>.004&&result.MaximumDeviationM<.006,"tolerance/distance incorrect");Reject(()=>RedlineComparison.Outlines(Square(),Square(),0));});
        Check("unsupported_outline_never_passes",()=>Assert(!RedlineComparison.Outlines(Square(),new RedlineOutline{UnsupportedReason="multiple rings"},.01).Passed,"unsupported passed"));
        Check("matching_pair_is_not_duplicate_and_reports_actual_gap",()=>{var result=RedlineComparison.Pair(Carrier(RedlineRoles.NetLand,1,0,.3),Carrier(RedlineRoles.Control,2,-.4,-.1),0,.01,.001);Assert(result.Passed&&Math.Abs(result.GapM.Value-.1)<1e-9,"separated pair failed");});
        Check("top_faces_separate_but_thick_solids_overlap_fails",()=>{var result=RedlineComparison.Pair(Carrier(RedlineRoles.NetLand,1,0,.3),Carrier(RedlineRoles.Control,2,-.1,.1),10,.01,.001);Assert(!result.Passed&&result.IntersectionVolumeM3==10,"solid collision passed");});
        Check("touching_no_boolean_overlap_still_fails_gap",()=>Assert(!RedlineComparison.Pair(Carrier(RedlineRoles.NetLand,1,0,.3),Carrier(RedlineRoles.Control,2,-.3,0),0,.01,.001).Passed,"touching solids passed"));
        Check("unverified_solids_or_boolean_failure_cannot_pass",()=>{var a=Carrier(RedlineRoles.NetLand,1,0,.3);a.SolidVerified=false;Assert(!RedlineComparison.Pair(a,Carrier(RedlineRoles.Control,2,-.4,-.1),0,.01,.001).Passed,"unsupported solid passed");a.SolidVerified=true;Assert(!RedlineComparison.Pair(a,Carrier(RedlineRoles.Control,2,-.4,-.1),null,.01,.001).Passed,"missing collision check passed");});
        Check("pair_checks_outline_collision_and_carrier_identity_independently",()=>{var a=Carrier(RedlineRoles.NetLand,1,0,.3);var b=Carrier(RedlineRoles.Control,2,-.4,-.1);b.Outline=Square(1);Assert(!RedlineComparison.Pair(a,b,0,.01,.001).Passed,"pair ignored horizontal offset");b.Outline=Square();Assert(!RedlineComparison.Pair(a,b,.5,.01,.001).Passed,"pair ignored actual solid collision");b.ElementId=1;Assert(!RedlineComparison.Pair(a,b,0,.01,.001).Passed,"same object accepted as two carriers");});
        Check("only_explicit_classified_exact_control_fields_resolve",()=>{var row=new ModelElementCheck{Classified=true,Slot="规划控制线",Name="用地红线",Fields=new[]{new FieldCheck{PropertySet=ControlLinePolicy.PropertySet,Property="名称",Value="净用地控制红线"},new FieldCheck{PropertySet=ControlLinePolicy.PropertySet,Property="红线类型",Value="净用地控制红线"}}};Assert(RedlineRoles.Resolve(row)==RedlineRoles.Control,"confirmed role lost");row.Fields[1].Value="用地红线";Assert(RedlineRoles.Resolve(row)==null,"alias/partial label accepted");row.Slot="规划净用地";Assert(RedlineRoles.Resolve(row)==RedlineRoles.NetLand,"net land lost");row.Classified=false;Assert(RedlineRoles.Resolve(row)==null,"unclassified row accepted");});
        Check("catalog_entity_variants_do_not_duplicate_control_fields",()=>{var sources=new System.Collections.Generic.Dictionary<string,string>{{"规划控制线名称",RedlineRoles.Control},{"红线类型",RedlineRoles.Control}};var fields=RedlineRoles.ControlFields(name=>sources[name]);var row=new ModelElementCheck{Classified=true,Slot="规划控制线",Fields=fields};Assert(fields.Length==2&&RedlineRoles.Resolve(row)==RedlineRoles.Control,"same control source declared for slab/proxy was counted twice");});
        Check("manual_data_json_roundtrip_preserves_metadata",()=>{var data=ManualData();data.SourcePath="人工资料.xlsx";data.SourceHash="abc";data.CoordinateSystemName="独立坐标";var copy=RedlineDataPolicy.Deserialize(RedlineDataPolicy.Serialize(data));Assert(copy.Points.Length==4&&copy.Points[2].X==10&&copy.SourcePath=="人工资料.xlsx"&&copy.Axes==RedlineAxes.XEastYNorth&&copy.Accepted,"storage data changed");Reject(()=>RedlineDataPolicy.Deserialize("{\"Version\":99}"));});
        Check("unsupported_metadata_enum_cannot_be_persisted",()=>{var data=ManualData();data.Frame=(RedlineFrame)99;Reject(()=>RedlineDataPolicy.Serialize(data));});
        Check("xlsx_reads_template_points_with_cell_provenance",()=>{var path=Workbook("manual-points",Rows());var data=RedlineWorkbook.Read(path);Assert(data.Points.Length==4&&data.Points[2].X==10&&data.Points[0].SourceCellX=="B3"&&data.SourceHash.Length==64,"manual data missing");Assert(!data.Accepted&&data.Frame==RedlineFrame.Unknown,"import guesses acceptance/frame");});
        Check("empty_template_does_not_invent_zero_points",()=>{var path=Workbook("blank","<row r='3'><c r='A3'><v>1</v></c></row>");var data=RedlineWorkbook.Read(path);Assert(data.Points.Length==0&&data.ImportIssues.Length>0&&!RedlineDataPolicy.Validate(data).ValidCoordinates,"blank coordinates became zero");});
        Check("cached_formula_is_not_authoritative_manual_coordinate",()=>{var path=Workbook("formula",Rows().Replace("<c r='B3'><v>0</v></c>","<c r='B3'><f>1-1</f><v>0</v></c>"));Assert(RedlineWorkbook.Read(path).ImportIssues.Length>0,"formula accepted as manual");});
        Check("wrong_template_header_blocks_import",()=>Reject(()=>RedlineWorkbook.Read(Workbook("wrong",Rows(),title:"其他坐标"))));
        Check("xlsx_export_preserves_template_and_manual_points",()=>{var data=ManualData();var path=Path.Combine(output,"export-"+Guid.NewGuid().ToString("N")+".xlsx");RedlineWorkbook.Write(path,data);var copy=RedlineWorkbook.Read(path);Assert(copy.Points.Length==4&&copy.Points[3].Y==10&&copy.ImportIssues.Length==0,"export changed points/template");using(var zip=ZipFile.OpenRead(path)){var xml=XDocument.Load(zip.GetEntry("xl/worksheets/sheet1.xml").Open());Assert(xml.Descendants().Any(e=>e.Name.LocalName=="mergeCell"&&(string)e.Attribute("ref")=="A1:C1"),"title merge lost");}});
        Check("export_rejects_unaccepted_model_source_or_original_overwrite",()=>{var data=ManualData();data.Accepted=false;Reject(()=>RedlineWorkbook.Write(Path.Combine(output,"unaccepted.xlsx"),data));data.Accepted=true;data.Source="MODEL";Reject(()=>RedlineWorkbook.Write(Path.Combine(output,"model.xlsx"),data));data.Source="MANUAL";data.SourcePath=Workbook("protected",Rows());var original=File.ReadAllBytes(data.SourcePath);Reject(()=>RedlineWorkbook.Write(data.SourcePath,data));Assert(original.SequenceEqual(File.ReadAllBytes(data.SourcePath)),"original modified");});
        RedlineWindowTests.Run(Check,output);
        if(args.Length>1)Check("supplied_original_template_read_does_not_modify_source",()=>{var original=File.ReadAllBytes(args[1]);var data=RedlineWorkbook.Read(args[1]);Assert(original.SequenceEqual(File.ReadAllBytes(args[1]))&&!data.Accepted&&data.Unit==RedlineUnit.Unknown&&data.Frame==RedlineFrame.Unknown&&data.Axes==RedlineAxes.Unknown,"original changed or metadata guessed");Console.WriteLine("SOURCE points="+data.Points.Length+"; issues="+string.Join(";",data.ImportIssues)+"; sha256="+data.SourceHash);});
        File.WriteAllText(Path.Combine(output,"redline-tests.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{tests,failures,passed=tests-failures,scope="Pure redline/XLSX behavior and actual standalone WPF with fake document session. Revit API classes separately compiled; native shared-point/solid/save-reopen acceptance remains required."}));
        Console.WriteLine("RESULT failures="+failures+"; tests="+tests);return failures==0?0:1;
    }
}
